    "onb.music.sub": "இந்த நகரத்திற்கு தனிப்பட்ட ரேடியோ உள்ளது — அமைதியான, விளம்பரமில்லா நிலையங்கள். நீங்கள் விரும்பினால்: இப்போது இயக்கவும், அல்லது அமைதியாக இருக்கவும்.",
